import { test } from "node:test";
import assert from "node:assert/strict";
import { formatDuration } from "../src/duration.mjs";

test("zero", () => {
  assert.equal(formatDuration(0), "0s");
});

test("seconds only", () => {
  assert.equal(formatDuration(45), "45s");
});

test("minutes and seconds, no zero padding", () => {
  assert.equal(formatDuration(60), "1m0s");
  assert.equal(formatDuration(61), "1m1s");
  assert.equal(formatDuration(605), "10m5s");
});

test("hours, minutes and seconds", () => {
  assert.equal(formatDuration(3600), "1h0m0s");
  assert.equal(formatDuration(3661), "1h1m1s");
  assert.equal(formatDuration(7325), "2h2m5s");
});

test("negative durations are rejected", () => {
  assert.throws(() => formatDuration(-1), RangeError);
});

test("non-integer seconds are rejected", () => {
  assert.throws(() => formatDuration(1.5), RangeError);
  assert.throws(() => formatDuration("60"), TypeError);
});
